// Design: HumanLayer packages/git-attribution gate (Apache-2.0).
// The upstream tree was not in the local sources checkout, so this is a rewrite.
// Rust src-tauri/src/attribution/logic.rs must agree with these rules.

import { normalizeLine } from "./evidence/journal-overlap/normalize";

const LEAD = /^(import |from |require\(|require |use |using |#include |package )/i;
const MARKERS = [
  "all rights reserved",
  "spdx-license-identifier",
  "do not edit",
  "generated by",
  "code generated",
];

/** ASCII A-Z only, so the gate matches the Rust port on every letter. */
function asciiLower(text: string): string {
  let out = "";
  for (const c of text) {
    const code = c.charCodeAt(0);
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : c;
  }
  return out;
}

/** A line that carries no authorship: too short, no letter, an import, or a banner. */
export function isBoilerplate(line: string): boolean {
  const text = normalizeLine(line);
  if (text.length < 8) return true;
  if (!/\p{L}/u.test(text)) return true;
  if (LEAD.test(text)) return true;
  const lower = asciiLower(text);
  return MARKERS.some((marker) => lower.includes(marker));
}
